package com.hiretrack.controller;import com.hiretrack.entity.User;import com.hiretrack.repository.UserRepository;import com.hiretrack.security.JwtService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.authentication.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController{private final UserRepository users;private final PasswordEncoder encoder;private final AuthenticationManager manager;private final JwtService jwt;public AuthController(UserRepository u,PasswordEncoder e,AuthenticationManager m,JwtService j){users=u;encoder=e;manager=m;jwt=j;}
public record Register(@NotBlank String fullName,@Email @NotBlank String email,@Size(min=8) String password,String degree,Integer graduationYear){}public record Login(@Email @NotBlank String email,@NotBlank String password){}
private Map<String,Object> result(User u){return Map.of("token",jwt.generate(u.getEmail()),"user",Map.of("id",u.getId(),"fullName",u.getFullName(),"email",u.getEmail(),"degree",u.getDegree()==null?"":u.getDegree(),"graduationYear",u.getGraduationYear()==null?0:u.getGraduationYear()));}
@PostMapping("/register")public ResponseEntity<?> register(@Valid @RequestBody Register r){String email=r.email().toLowerCase();if(users.existsByEmail(email))return ResponseEntity.status(409).body(Map.of("message","Email already registered"));User u=new User();u.setFullName(r.fullName());u.setEmail(email);u.setPassword(encoder.encode(r.password()));u.setDegree(r.degree());u.setGraduationYear(r.graduationYear());users.save(u);return ResponseEntity.ok(result(u));}
@PostMapping("/login")public Map<String,Object> login(@Valid @RequestBody Login r){manager.authenticate(new UsernamePasswordAuthenticationToken(r.email().toLowerCase(),r.password()));return result(users.findByEmail(r.email().toLowerCase()).orElseThrow());}}